import { useEffect, useState } from 'react';
import { ActivityIndicator, Pressable, StyleSheet, Text, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { router, useLocalSearchParams } from 'expo-router';
import { Ionicons } from '@expo/vector-icons';
import { useQueryClient } from '@tanstack/react-query';

import { DesignColors, DesignRadius, DesignSpacing, DesignTypography, fontFamily } from '@/constants/design';
import { useVerifyLocationPayment } from '@/hooks/use-location-access';
import { verifyLodgePayment } from '@/services/lodge-payment-service';

type Status = 'verifying' | 'unlocked' | 'failed';
type PaymentKind = 'location' | 'tour' | 'lodge';

export default function LocationUnlockCallbackScreen() {
  const params = useLocalSearchParams<{
    listingId?: string;
    reference?: string;
    trxref?: string;
    kind?: string;
    bookingId?: string;
    date?: string;
    time?: string;
    creditId?: string;
    targetOccupancy?: string;
  }>();
  const { mutateAsync: verify } = useVerifyLocationPayment();
  const queryClient = useQueryClient();
  const [status, setStatus] = useState<Status>('verifying');

  const listingId = params.listingId ?? '';
  const reference = params.reference ?? params.trxref ?? '';
  const kind: PaymentKind = params.kind === 'tour' ? 'tour' : params.kind === 'lodge' ? 'lodge' : 'location';
  const creditId = params.creditId ?? '';
  const targetOccupancy = Number(params.targetOccupancy ?? '1');

  useEffect(() => {
    if (!reference || !listingId) {
      setStatus('failed');
      return;
    }
    let cancelled = false;

    if (kind === 'lodge') {
      verifyLodgePayment(reference)
        .then(async (result) => {
          if (cancelled) return;
          if (result.verified) {
            await queryClient.invalidateQueries({ queryKey: ['user-slot-credits'] });
            if (cancelled) return;
            if (targetOccupancy === 1) {
              router.replace(`/property/booking?id=${encodeURIComponent(creditId)}`);
            } else {
              router.replace('/property/lobby');
            }
            return;
          }
          setStatus('failed');
        })
        .catch(() => {
          if (!cancelled) setStatus('failed');
        });
      return () => { cancelled = true; };
    }

    verify(reference)
      .then((result) => {
        if (cancelled) return;
        if (result.unlocked) {
          queryClient.invalidateQueries({ queryKey: ['location-access'] });
          queryClient.invalidateQueries({ queryKey: ['tour-bookings'] });
        }
        if (result.unlocked && result.kind === 'tour') {
          router.replace(
            `/property/tour-pass?id=${encodeURIComponent(listingId)}&bookingId=${encodeURIComponent(result.bookingId ?? '')}&date=${encodeURIComponent(params.date ?? '')}&time=${encodeURIComponent(params.time ?? '')}`,
          );
          return;
        }
        setStatus(result.unlocked ? 'unlocked' : 'failed');
      })
      .catch(() => {
        if (!cancelled) setStatus('failed');
      });
    return () => { cancelled = true; };
  }, [reference, listingId, verify, kind, creditId, targetOccupancy, params.date, params.time, params.bookingId, queryClient]);

  const goToProperty = () => {
    router.replace({ pathname: '/property/[id]', params: { id: listingId } });
  };

  return (
    <SafeAreaView style={styles.safe}>
      <View style={styles.content}>
        {status === 'verifying' && (
          <>
            <View style={styles.badge}>
              <ActivityIndicator color={DesignColors.primaryBright} />
            </View>
            <Text style={styles.title}>Confirming your payment</Text>
            <Text style={styles.subtitle}>Verifying your unlock for this property…</Text>
          </>
        )}

        {status === 'unlocked' && (
          <>
            <View style={styles.badge}>
              <Ionicons name="checkmark-done" size={40} color={DesignColors.onPrimary} />
            </View>
            <Text style={styles.title}>Location Unlocked</Text>
            <Text style={styles.subtitle}>
              You now have access to the exact GPS coordinates and directions for this property.
            </Text>
          </>
        )}

        {status === 'failed' && (
          <>
            <View style={[styles.badge, styles.badgeError]}>
              <Ionicons name="alert-circle-outline" size={40} color={DesignColors.error} />
            </View>
            <Text style={styles.title}>Payment not found</Text>
            <Text style={styles.subtitle}>
              We couldn&apos;t confirm your payment. If you were charged, your unlock will appear automatically.
            </Text>
          </>
        )}
      </View>

      {status !== 'verifying' && (
        <View style={styles.footer}>
          <Pressable accessibilityRole="button" style={styles.button} onPress={goToProperty}>
            <Ionicons name="arrow-back" size={18} color={DesignColors.onPrimary} />
            <Text style={styles.buttonText}>{kind === 'tour' ? 'Back to Property' : 'Back to Property'}</Text>
          </Pressable>
        </View>
      )}
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  safe: { flex: 1, backgroundColor: DesignColors.surface },
  content: {
    flex: 1,
    alignItems: 'center',
    justifyContent: 'center',
    paddingHorizontal: DesignSpacing.xl,
    gap: DesignSpacing.md,
  },
  badge: {
    width: 72,
    height: 72,
    borderRadius: 36,
    alignItems: 'center',
    justifyContent: 'center',
    backgroundColor: DesignColors.primary,
    marginBottom: DesignSpacing.sm,
  },
  badgeError: {
    backgroundColor: DesignColors.dangerContainer,
  },
  title: {
    ...DesignTypography.headlineMd,
    color: DesignColors.onSurface,
    fontFamily,
    fontWeight: '800',
    textAlign: 'center',
  },
  subtitle: {
    ...DesignTypography.bodyMd,
    color: DesignColors.onSurfaceVariant,
    fontFamily,
    textAlign: 'center',
    lineHeight: 22,
    maxWidth: 320,
  },
  footer: {
    paddingHorizontal: DesignSpacing.xl,
    paddingBottom: DesignSpacing.xl,
  },
  button: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'center',
    gap: DesignSpacing.sm,
    height: 54,
    borderRadius: DesignRadius.full,
    backgroundColor: DesignColors.primary,
  },
  buttonText: {
    ...DesignTypography.labelLg,
    color: DesignColors.onPrimary,
    fontFamily,
    fontWeight: '700',
  },
});

import { useCallback, useEffect, useState } from 'react';
import { ActivityIndicator, Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';
import { WebBlurView } from '@/components/ui/web-blur-view';
import { SafeAreaView } from 'react-native-safe-area-context';

import { BackButton } from '@/components/ui/back-button';
import { DesignColors, DesignTypography, fontFamily } from '@/constants/design';
import { useAuth } from '@/context/auth-context';
import { fetchAdminListings, type AdminListing } from '@/services/adminService';
import { FeaturedListingCard } from './featured-listing-card';
import { ManagementToolsGrid } from './management-tools-grid';

export function AdminDashboardScreen() {
  const { profile } = useAuth();
  const [businessName, setBusinessName] = useState<string | null>(null);
  const [operatingCity, setOperatingCity] = useState<string | null>(null);
  const [listings, setListings] = useState<AdminListing[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!profile?.id) return;
    fetchAdminListings(profile.id).then((listingsData) => {
      setBusinessName(profile.full_name);
      setOperatingCity(profile.city);
      setListings(listingsData);
      setLoading(false);
    });
  }, [profile?.id]);

  const initials = useCallback((name: string) => {
    return name.split(' ').map((w) => w[0]).join('').toUpperCase().slice(0, 2);
  }, []);

  if (loading) {
    return (
      <SafeAreaView style={styles.safe} edges={['top']}>
        <View style={styles.loadingWrap}>
          <ActivityIndicator size="large" color={DesignColors.primary} />
        </View>
      </SafeAreaView>
    );
  }

  const featuredListing = listings.find((l) => l.featured) ?? null;

  return (
    <SafeAreaView style={styles.safe} edges={['top']}>
      <ScrollView bounces={false} contentContainerStyle={styles.content} showsVerticalScrollIndicator={false}>
        <View style={styles.header}>
          <View style={styles.avatarSection}>
            <View style={styles.avatarWrap}>
              <WebBlurView intensity={20} tint="dark" style={styles.avatarBlur} />
              <Text style={styles.avatarText}>{businessName ? initials(businessName) : '?'}</Text>
            </View>
            <View style={styles.backBtnWrap}>
              <BackButton hasBackground={false} />
            </View>
          </View>
          <View style={styles.headerText}>
            <Text style={styles.headerTitle}>{businessName || 'Admin Dashboard'}</Text>
            <Text style={styles.headerSub}>
              {operatingCity || 'City'} <Text style={styles.dot}>{'  \u2022  '}</Text> Admin
            </Text>
          </View>
        </View>

        <View style={styles.section}>
          <Text style={styles.sectionTitle}>Management Tools</Text>
          <ManagementToolsGrid />
        </View>

        <View style={styles.section}>
          <View style={styles.featuredHeader}>
            <Text style={styles.sectionTitle}>Featured Listing</Text>
            <Pressable>
              <Text style={styles.seeAll}>View All</Text>
            </Pressable>
          </View>
          <FeaturedListingCard listing={featuredListing} />
        </View>
      </ScrollView>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  safe: { flex: 1, backgroundColor: DesignColors.surfaceContainerLowest },
  loadingWrap: { flex: 1, alignItems: 'center', justifyContent: 'center' },
  content: { padding: 20, gap: 32, paddingBottom: 128 },
  header: { flexDirection: 'row', alignItems: 'center', gap: 20, paddingTop: 24 },
  avatarSection: { position: 'relative' },
  avatarWrap: {
    width: 64, height: 64, borderRadius: 22, overflow: 'hidden',
    backgroundColor: DesignColors.glassStrong, borderWidth: 1, borderColor: DesignColors.glassBorder,
    alignItems: 'center', justifyContent: 'center',
    transform: [{ rotate: '6deg' }],
    shadowColor: DesignColors.primary, shadowOffset: { width: 0, height: 4 },
    shadowOpacity: 0.4, shadowRadius: 20, elevation: 10,
  },
  avatarBlur: { ...StyleSheet.absoluteFill },
  avatarText: { fontSize: 20, fontWeight: '900', color: DesignColors.onSurface, fontFamily, transform: [{ rotate: '-6deg' }] },
  backBtnWrap: { position: 'absolute', top: -24, left: -8, zIndex: 10 },
  headerText: { flex: 1 },
  headerTitle: { ...DesignTypography.headlineMd, fontSize: 24, letterSpacing: -0.24, color: DesignColors.onSurface, fontFamily },
  headerSub: { ...DesignTypography.labelCaps, fontSize: 11, letterSpacing: 0.6, color: DesignColors.onSurfaceVariant, fontFamily, marginTop: 2 },
  dot: { color: DesignColors.onSurfaceVariant },
  section: { gap: 16 },
  sectionTitle: { ...DesignTypography.labelCaps, color: DesignColors.onSurfaceVariant, fontFamily, paddingHorizontal: 2 },
  featuredHeader: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', paddingHorizontal: 2 },
  seeAll: { ...DesignTypography.labelSm, fontWeight: '600', color: DesignColors.primary, fontFamily },
});

