                </LinearGradient>
              </Defs>
              <Rect width="100%" height="100%" fill="url(#heroMask)" />
            </Svg>
          </View>
        </>
      ) : (
        <View style={styles.heroFallback}>
          <Ionicons name="business-outline" size={28} color={DesignColors.primaryBright} />
