import { Ionicons } from '@expo/vector-icons';
import { useCallback, useEffect, useRef, useState } from 'react';
import { Animated, Easing, Pressable, RefreshControl, ScrollView, StyleSheet, Text, View } from 'react-native';

import { DiscoverBottomNav } from '@/components/home/discover-bottom-nav';
import { FloatingBadge } from '@/components/ui/floating-badge';
import { DesignColors, DesignSpacing, DesignTypography, fontFamily } from '@/constants/design';

interface NetworkErrorScreenProps {
  onRetry: () => void;
  subtitle?: string;
}

export function NetworkErrorScreen({
  onRetry,
  subtitle = 'Check your network, or maybe our maintenance team is giving the buildings a fresh coat of digital paint. Let\u2019s try again in a moment.',
}: NetworkErrorScreenProps) {
  const floatAnim = useRef(new Animated.Value(0)).current;
  const [refreshing, setRefreshing] = useState(false);

  useEffect(() => {
    const loop = Animated.loop(
      Animated.sequence([
        Animated.timing(floatAnim, {
          toValue: 1,
          duration: 4000,
          easing: Easing.inOut(Easing.sin),
          useNativeDriver: true,
        }),
        Animated.timing(floatAnim, {
          toValue: 0,
          duration: 4000,
          easing: Easing.inOut(Easing.sin),
          useNativeDriver: true,
        }),
      ]),
    );
    loop.start();
    return () => loop.stop();
  }, [floatAnim]);

  const mainTranslateY = floatAnim.interpolate({
    inputRange: [0, 0.5, 1],
    outputRange: [0, -15, 0],
  });

  const mainRotate = floatAnim.interpolate({
    inputRange: [0, 0.5, 1],
    outputRange: ['6deg', '4deg', '6deg'],
  });

  const handleRefresh = useCallback(() => {
    setRefreshing(true);
    setTimeout(() => {
      setRefreshing(false);
      onRetry();
    }, 1300);
  }, [onRetry]);

  return (
    <View style={styles.safe}>
      <ScrollView
        contentContainerStyle={styles.scroll}
        keyboardShouldPersistTaps="handled"
        showsVerticalScrollIndicator={false}
        refreshControl={
          <RefreshControl refreshing={refreshing} onRefresh={handleRefresh} tintColor={DesignColors.primary} />
        }
      >
        <View style={styles.center}>
          <View style={styles.iconArea}>
            <Animated.View
              style={[
                styles.mainCard,
                {
                  transform: [{ translateY: mainTranslateY }, { rotate: mainRotate }],
                },
              ]}
            >
              <Ionicons name="wifi-outline" size={52} color={DesignColors.primary} />

              <FloatingBadge
                icon="home"
                size={18}
                top={-8}
                right={-8}
                rotate="-12deg"
                color={DesignColors.secondary}
                shape="rounded"
              />

              <FloatingBadge
                icon="cloud-offline-outline"
                size={18}
                bottom={-4}
                left={-14}
                rotate="12deg"
                color={DesignColors.tertiary}
                shape="circle"
                delay={600}
              />
            </Animated.View>
          </View>

          <Text style={styles.title}>Oops! Gida couldn&apos;t connect</Text>
          <Text style={styles.subtitle}>{subtitle}</Text>

          <Pressable onPress={onRetry} style={styles.button}>
            <Ionicons name="refresh" size={18} color={DesignColors.onPrimary} />
            <Text style={styles.buttonText}>Try Reconnecting</Text>
          </Pressable>

          <Text style={styles.hint}>Or tap to refresh manually.</Text>
        </View>
      </ScrollView>

      <DiscoverBottomNav activeTab="discover" />
    </View>
  );
}

const styles = StyleSheet.create({
  safe: {
    flex: 1,
    backgroundColor: DesignColors.surfaceContainerLowest,
  },
  scroll: {
    flexGrow: 1,
  },
  center: {
    flex: 1,
    alignItems: 'center',
    justifyContent: 'center',
    paddingHorizontal: DesignSpacing.marginMobile,
    gap: DesignSpacing.md,
  },
  iconArea: {
    width: 200,
    height: 200,
    alignItems: 'center',
    justifyContent: 'center',
    marginBottom: DesignSpacing.sm,
  },
  mainCard: {
    width: 144,
    height: 144,
    borderRadius: 40,
    alignItems: 'center',
    justifyContent: 'center',
    backgroundColor: DesignColors.glassFill,
    borderWidth: 1,
    borderColor: DesignColors.glassBorder,
  },
  title: {
    ...DesignTypography.headlineMd,
    color: DesignColors.onSurface,
    fontFamily,
    fontWeight: '700',
    textAlign: 'center',
  },
  subtitle: {
    ...DesignTypography.bodyMd,
    color: DesignColors.onSurfaceVariant,
    fontFamily,
    textAlign: 'center',
    maxWidth: 320,
    lineHeight: 22,
  },
  button: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: DesignSpacing.sm,
    paddingHorizontal: 32,
    paddingVertical: 16,
    borderRadius: 999,
    backgroundColor: DesignColors.primary,
    marginTop: DesignSpacing.sm,
  },
  buttonText: {
    ...DesignTypography.bodyLg,
    color: DesignColors.onPrimary,
    fontFamily,
    fontWeight: '700',
  },
  hint: {
    ...DesignTypography.bodyMd,
    color: DesignColors.onSurfaceVariant,
    fontFamily,
    textAlign: 'center',
    marginTop: -DesignSpacing.xs,
  },
});

