import { useCallback, useEffect, useRef } from 'react';
import { Animated, Easing, Pressable, RefreshControl, ScrollView, StyleSheet, Text, View } from 'react-native';

import { Ionicons } from '@expo/vector-icons';
import { FloatingBadge } from '@/components/ui/floating-badge';
import { SearchBar } from '@/components/ui/search-bar';
import { DesignColors, DesignSpacing, DesignTypography, fontFamily } from '@/constants/design';

interface NoResultsFoundScreenProps {
  query: string;
  onQueryChange: (value: string) => void;
  onAdjustFilters: () => void;
  onRefresh: () => void;
  refreshing: boolean;
  showSearchBar?: boolean;
  subtitle?: string;
}

export function NoResultsFoundScreen({
  query,
  onQueryChange,
  onAdjustFilters,
  onRefresh,
  refreshing,
  showSearchBar = true,
  subtitle = "We couldn't find any available apartments or active roommate requests matching your current filters around campus.",
}: NoResultsFoundScreenProps) {
  const floatAnim = useRef(new Animated.Value(0)).current;

  useEffect(() => {
    const loop = Animated.loop(
      Animated.sequence([
        Animated.timing(floatAnim, {
          toValue: 1,
          duration: 4000,
          easing: Easing.inOut(Easing.sin),
          useNativeDriver: true,
        }),
        Animated.timing(floatAnim, {
          toValue: 0,
          duration: 4000,
          easing: Easing.inOut(Easing.sin),
          useNativeDriver: true,
        }),
      ]),
    );
    loop.start();
    return () => loop.stop();
  }, [floatAnim]);

  const mainTranslateY = floatAnim.interpolate({
    inputRange: [0, 0.5, 1],
    outputRange: [0, -15, 0],
  });

  const mainRotate = floatAnim.interpolate({
    inputRange: [0, 0.5, 1],
    outputRange: ['6deg', '4deg', '6deg'],
  });

  const handleRefresh = useCallback(() => {
    onRefresh();
  }, [onRefresh]);

  return (
    <View style={styles.safe}>
      <ScrollView
        contentContainerStyle={styles.scroll}
        keyboardShouldPersistTaps="handled"
        showsVerticalScrollIndicator={false}
        refreshControl={
          <RefreshControl refreshing={refreshing} onRefresh={handleRefresh} tintColor={DesignColors.primary} />
        }
      >
        {showSearchBar ? (
          <View style={styles.searchWrap}>
            <SearchBar value={query} onChangeText={onQueryChange} placeholder="Locations and property type" hasFilter onFilterPress={onAdjustFilters} />
          </View>
        ) : null}

        <View style={styles.center}>
          <View style={styles.iconArea}>
            <Animated.View
              style={[
                styles.mainCard,
                {
                  transform: [{ translateY: mainTranslateY }, { rotate: mainRotate }],
                },
              ]}
            >
              <Ionicons name="home" size={52} color={DesignColors.primary} />

              <FloatingBadge
                icon="location-outline"
                size={18}
                top={-8}
                right={-8}
                rotate="-12deg"
                color={DesignColors.secondary}
                shape="rounded"
