import React, { createContext, useContext, useState, useCallback, useEffect, useRef } from 'react';
import { Animated, StyleSheet, Text, View, Dimensions, Pressable, SafeAreaView } from 'react-native';
import { WebBlurView } from '@/components/ui/web-blur-view';
import { Ionicons } from '@expo/vector-icons';
import { DesignColors, DesignRadius, DesignSpacing, DesignTypography, fontFamily } from '@/constants/design';

// ==========================================
// 1. TYPES & INTERFACES
// ==========================================
export interface ToastData {
  id: string;
  title?: string;
  message: string;
  type: 'success' | 'error' | 'info';
}

interface ToastContextType {
  showToast: (config: { title?: string; message: string; type: 'success' | 'error' | 'info' }) => void;
}

const ToastContext = createContext<ToastContextType | undefined>(undefined);

const TOAST_DURATION = 4000;

// ==========================================
// 2. ANIMATED TOAST CARD (INTERNAL COMPONENT)
// ==========================================
function ToastCard({ toast, onDismiss }: { toast: ToastData; onDismiss: (id: string) => void }) {
  const translateY = useRef(new Animated.Value(-80)).current;
  const opacity = useRef(new Animated.Value(0)).current;
  const progress = useRef(new Animated.Value(1)).current;

  const handleDismiss = useCallback(() => {
    Animated.parallel([
      Animated.timing(translateY, { toValue: -32, duration: 220, useNativeDriver: true }),
      Animated.timing(opacity, { toValue: 0, duration: 180, useNativeDriver: true }),
    ]).start(() => onDismiss(toast.id));
  }, [onDismiss, toast.id, translateY, opacity]);

  useEffect(() => {
    Animated.parallel([
      Animated.spring(translateY, { toValue: 0, damping: 18, stiffness: 260, mass: 0.9, useNativeDriver: true }),
      Animated.timing(opacity, { toValue: 1, duration: 240, useNativeDriver: true }),
    ]).start();

    Animated.timing(progress, { toValue: 0, duration: TOAST_DURATION, useNativeDriver: true }).start();

    const timer = setTimeout(handleDismiss, TOAST_DURATION);
    return () => clearTimeout(timer);
  }, [handleDismiss, translateY, opacity, progress]);

  const themes = {
    success: { accent: DesignColors.success, icon: 'checkmark-circle', label: 'Success' },
    error: { accent: DesignColors.danger, icon: 'alert-circle', label: 'Error' },
    info: { accent: DesignColors.info, icon: 'information-circle', label: 'Heads up' },
  } as const;

  const theme = themes[toast.type];
  const title = toast.title ?? theme.label;

  return (
    <Animated.View style={[styles.wrapper, { transform: [{ translateY }], opacity }]}>
      <Pressable onPress={handleDismiss} style={styles.card} focusable={false} accessible={false}>
        <WebBlurView intensity={28} tint="dark" style={styles.blur} />
        <View style={[styles.accentBar, { backgroundColor: theme.accent }]} />
        <View style={[styles.iconWrap, { backgroundColor: theme.accent }]}>
          <Ionicons name={theme.icon} size={18} color={DesignColors.surfaceContainerLowest} />
        </View>
        <View style={styles.textContainer}>
          <Text style={styles.title} numberOfLines={1}>{title}</Text>
          <Text style={styles.message} numberOfLines={2}>{toast.message}</Text>
        </View>
        <Ionicons name="close" size={18} color={DesignColors.outline} />
        <View style={styles.progressTrack}>
          <Animated.View
            style={[styles.progressBar, { backgroundColor: theme.accent, transform: [{ scaleX: progress }] }]}
          />
        </View>
      </Pressable>
    </Animated.View>
  );
}

// ==========================================
// 3. GLOBAL CONTEXT PROVIDER
// ==========================================
export function ToastProvider({ children }: { children: React.ReactNode }) {
  const [toasts, setToasts] = useState<ToastData[]>([]);

  const showToast = useCallback(({ title, message, type }: Omit<ToastData, 'id'>) => {
    const id = Math.random().toString(36).substring(2, 9);
    setToasts((prev) => [...prev, { id, title, message, type }]);
  }, []);

  const removeToast = useCallback((id: string) => {
    setToasts((prev) => prev.filter((t) => t.id !== id));
  }, []);

  return (
    <ToastContext.Provider value={{ showToast }}>
      {children}
      {toasts.length > 0 && (
        <SafeAreaView style={styles.globalContainer} pointerEvents="box-none">
          <View style={styles.toastStack} pointerEvents="box-none">
            {toasts.map((toast) => (
              <ToastCard key={toast.id} toast={toast} onDismiss={removeToast} />
            ))}
          </View>
        </SafeAreaView>
      )}
    </ToastContext.Provider>
  );
}

// ==========================================
// 4. EXPORTED HOOK FOR CONSUMPTION
// ==========================================
export function useAppToast() {
  const context = useContext(ToastContext);
  if (!context) throw new Error('useAppToast must be used within a ToastProvider');
  return context;
}

// ==========================================
// 5. COMPONENT STYLING
// ==========================================
const styles = StyleSheet.create({
  globalContainer: {
    position: 'absolute',
    top: 50,
    left: 0,
    right: 0,
    zIndex: 99999,
  },
  toastStack: {
    alignItems: 'center',
    width: '100%',
  },
  wrapper: {
    width: Dimensions.get('window').width,
    paddingHorizontal: DesignSpacing.md,
    marginTop: 8,
  },
  card: {
    flexDirection: 'row',
    alignItems: 'center',
    overflow: 'hidden',
    borderRadius: DesignRadius.lg,
    borderWidth: 1,
    borderColor: DesignColors.glassBorder,
    backgroundColor: DesignColors.glassFill,
    paddingVertical: 14,
    paddingHorizontal: DesignSpacing.md,
    shadowColor: DesignColors.surfaceContainerLowest,
    shadowOffset: { width: 0, height: 8 },
    shadowOpacity: 0.25,
    shadowRadius: 16,
    elevation: 8,
  },
  blur: {
    ...StyleSheet.absoluteFill,
  },
  accentBar: {
    position: 'absolute',
    left: 0,
    top: 0,
    bottom: 0,
    width: 4,
  },
  iconWrap: {
    width: 34,
    height: 34,
    borderRadius: DesignRadius.full,
    alignItems: 'center',
    justifyContent: 'center',
    marginRight: DesignSpacing.md,
  },
  textContainer: { flex: 1, paddingRight: DesignSpacing.sm },
  title: {
    ...DesignTypography.labelCaps,
    color: DesignColors.onSurfaceVariant,
    fontFamily,
    letterSpacing: 1.4,
    marginBottom: 2,
  },
  message: {
    ...DesignTypography.bodyMd,
    color: DesignColors.onSurface,
    fontFamily,
    lineHeight: 18,
  },
  progressTrack: {
    position: 'absolute',
    left: 0,
    right: 0,
    bottom: 0,
    height: 2,
    overflow: 'hidden',
  },
  progressBar: {
    width: '100%',
    height: '100%',
    transformOrigin: 'left',
  },
});

import { View, ViewStyle } from 'react-native';

type Props = {
  intensity?: number;
  tint?: string;
  style?: ViewStyle;
  children?: React.ReactNode;
};

export function WebBlurView({ intensity = 20, tint = 'dark', style, children }: Props) {
  const opacity = Math.min(intensity / 100, 1);
  const bgColor = tint === 'dark' ? `rgba(14, 14, 16, ${opacity})` : `rgba(255, 255, 255, ${opacity})`;

  return (
    <View
      style={[{ backgroundColor: bgColor }, style]}
      children={children}
    />
  );
}

import React, { createContext, useContext, useEffect, useState } from 'react';
import { useColorScheme } from 'react-native';

interface AppConfigContextType {
  isDarkMode: boolean;
}

const AppConfigContext = createContext<AppConfigContextType | undefined>(undefined);

export function AppConfigProvider({ children }: { children: React.ReactNode }) {
  const systemColorScheme = useColorScheme();
  const [isDarkMode, setIsDarkMode] = useState(systemColorScheme === 'dark');

  useEffect(() => {
    setIsDarkMode(systemColorScheme === 'dark');
  }, [systemColorScheme]);

  return (
    <AppConfigContext.Provider value={{ isDarkMode }}>
      {children}
    </AppConfigContext.Provider>
  );
}

export function useAppConfig() {
  const context = useContext(AppConfigContext);
  if (!context) throw new Error('useAppConfig must be used within an AppConfigProvider');
  return context;
}

import { createContext, useCallback, useContext, useEffect, useRef, useState, type ReactNode } from 'react';
import { AppState } from 'react-native';
import { useQueryClient } from '@tanstack/react-query';
import NetInfo from '@react-native-community/netinfo';
import { supabase } from '@/lib/supabase';
import { signOutUserAccount } from '@/services/authService';
import { cacheProfile, getCachedProfile, clearCachedProfile } from '@/services/offline-profile-store';

// Upper bound for any single launch-time network wait. The splash screen only
// ever covers this window — it can never hang indefinitely.
const SETTLE_TIMEOUT_MS = 10000;

function withTimeout<T>(promise: Promise<T>, ms: number): Promise<T> {
  let timer: ReturnType<typeof setTimeout> | undefined;
  const timeout = new Promise<never>((_, reject) => {
    timer = setTimeout(() => reject(new Error('Auth settle timed out')), ms);
  });
  return Promise.race([promise, timeout]).finally(() => clearTimeout(timer));
}

async function isOffline(): Promise<boolean> {
  try {
    const state = await NetInfo.fetch();
    return state.isConnected === false;
  } catch {
    return false;
  }
}

export type AdminRole = 'super_admin' | 'regional_admin' | 'field_admin';

export type AuthProfile = {
  id: string;
  email: string | null;
  full_name: string | null;
  username: string | null;
  avatar_url: string | null;
  bio: string | null;
  gender: 'MALE' | 'FEMALE' | null;
  is_student: boolean | null;
  is_admin: boolean | null;
  admin_role: AdminRole | null;
  assigned_region_id: string | null;
  city: string | null;
  school: string | null;
  onboarded: boolean | null;
  show_in_roommate_feed: boolean | null;
  birth_year: number | null;
  entry_year: number | null;
  program_duration: number | null;
  religion: string | null;
};

type AuthContextValue = {
  profile: AuthProfile | null;
  isLoading: boolean;
  isAuthenticated: boolean;
  // True when a Supabase session exists even if the profile row hasn't loaded
  // yet (e.g. offline on first run). Lets the router send the user to the
  // homepage best-effort instead of bouncing them to login.
  hasSession: boolean;
  refreshProfile: () => Promise<void>;
  signOut: () => Promise<void>;
};

const AuthContext = createContext<AuthContextValue | undefined>(undefined);

export function AuthProvider({ children }: { children: ReactNode }) {
  const queryClient = useQueryClient();
  const [profile, setProfile] = useState<AuthProfile | null>(null);
  const [hasSession, setHasSession] = useState(false);
  const [isLoading, setIsLoading] = useState(true);

  const fetchProfile = useCallback(async (userId: string, email: string | null = null) => {
    const { data: profileData, error } = await supabase
      .from('profiles')
      .select('*')
      .eq('id', userId)
      .single();

    if (error) {
      console.error('[Auth] Failed to fetch profile (will keep cached if available):', error.message);
      return;
    }

    const { data: adminData } = await supabase
      .from('admin_profiles')
      .select('role, assigned_region_id')
      .eq('id', userId)
      .maybeSingle();

    const merged: AuthProfile = {
      ...profileData,
      email: email ?? profile?.email ?? null,
      admin_role: adminData?.role ?? null,
      assigned_region_id: adminData?.assigned_region_id ?? null,
    };

    setProfile(merged);
    cacheProfile(merged);
  }, [profile?.email]);

  useEffect(() => {
    let cancelled = false;
    let realtimeCleanup: (() => void) | null = null;

    const attachRealtime = (userId: string) => {
      realtimeCleanup?.();
      const channel = supabase
        .channel(`profile-changes-${userId}`)
        .on(
          'postgres_changes',
          { event: 'UPDATE', schema: 'public', table: 'profiles', filter: `id=eq.${userId}` },
          () => {
            console.log('[Auth] Profile updated on the server — refreshing.');
            void fetchProfile(userId, profile?.email ?? null).catch((error) => {
              console.log('[Auth] Background profile refresh failed.', error);
            });
          },
        );
      channel.subscribe((status, err) => {
        if (status === 'CHANNEL_ERROR' || status === 'TIMED_OUT' || status === 'CLOSED') {
          console.log(`[Auth] Realtime channel status: ${status} (switching to manual refresh only)`, err ?? '');
        }
      });
      realtimeCleanup = () => void supabase.removeChannel(channel);
    };

    // Launch settle: cache-first so the homepage renders instantly, then a
    // bounded, silent background sync. The splash screen only ever covers the
    // no-cache determination window — never an unbounded network wait.
    const settle = async () => {
      const cached = getCachedProfile();
      if (cached && !cancelled) {
        setProfile(cached);
        setHasSession(true);
        setIsLoading(false);
      }

      let sessionUser: { id: string; email?: string | null } | null = null;
      try {
        const { data: { session } } = await withTimeout(supabase.auth.getSession(), SETTLE_TIMEOUT_MS);
        sessionUser = session?.user ?? null;
      } catch (error) {
        console.log('[Auth] Session check timed out or failed — continuing with cached state.', error);
      }
      if (cancelled) return;

      if (!sessionUser) {
        if (!cached) {
          setProfile(null);
          setHasSession(false);
        }
        setIsLoading(false);
        return;
      }

      setHasSession(true);
      attachRealtime(sessionUser.id);

      // Offline: stay on the cached/session state; the reconnect listener
      // below syncs silently when connectivity returns. No hiccup.
      if (await isOffline()) {
        setIsLoading(false);
        return;
      }

      try {
        await withTimeout(fetchProfile(sessionUser.id, sessionUser.email ?? null), SETTLE_TIMEOUT_MS);
      } catch (error) {
        console.log('[Auth] Background profile refresh failed — keeping current state.', error);
      } finally {
        if (!cancelled) setIsLoading(false);
      }
    };
    void settle();

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session?.user) {
        setHasSession(true);
        void fetchProfile(session.user.id, session.user.email ?? null).catch((error) => {
          console.log('[Auth] Background profile refresh failed.', error);
        });
        attachRealtime(session.user.id);
      } else {
        clearCachedProfile();
        setProfile(null);
        setHasSession(false);
        realtimeCleanup?.();
        realtimeCleanup = null;
      }
    });

    return () => {
      cancelled = true;
      subscription.unsubscribe();
      realtimeCleanup?.();
    };
  }, [fetchProfile]);

  // Silent catch-up when connectivity returns: refresh the profile in the
  // background without touching isLoading, so the user notices nothing.
  const firstNetRun = useRef(true);
  useEffect(() => {
    const unsubscribe = NetInfo.addEventListener((state) => {
      if (firstNetRun.current) {
        firstNetRun.current = false;
        return;
      }
      if (!state.isConnected) return;
      void (async () => {
        try {
          const { data: { session } } = await withTimeout(supabase.auth.getSession(), SETTLE_TIMEOUT_MS);
          if (!session?.user) return;
          setHasSession(true);
          await withTimeout(fetchProfile(session.user.id, session.user.email ?? null), SETTLE_TIMEOUT_MS);
        } catch (error) {
          console.log('[Auth] Reconnect refresh failed — will retry on next change.', error);
        }
      })();
    });
    return () => unsubscribe();
  }, [fetchProfile]);

  const refreshProfile = useCallback(async () => {
    const { data: { session } } = await supabase.auth.getSession();
    if (session?.user) {
      await fetchProfile(session.user.id, session.user.email ?? null);
    }
  }, [fetchProfile]);

  const appStateRef = useRef(AppState.currentState);

  useEffect(() => {
    const subscription = AppState.addEventListener('change', (nextState) => {
      if (appStateRef.current.match(/inactive|background/) && nextState === 'active') {
        void refreshProfile();
      }
      appStateRef.current = nextState;
    });
    return () => subscription.remove();
  }, [refreshProfile]);

  const signOut = useCallback(async () => {
    await signOutUserAccount();
    clearCachedProfile();
    queryClient.clear();
    setProfile(null);
    setHasSession(false);
  }, [queryClient]);

  return (
    <AuthContext.Provider
      value={{
        profile,
        isLoading,
        isAuthenticated: !!profile,
        hasSession,
        refreshProfile,
        signOut,
      }}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
}

