import { useState, useEffect } from 'react';
import { supabase } from '@/lib/supabase';
import { useAuth } from '@/context/auth-context';

export function useUnreadMessages() {
  const { profile } = useAuth();
  const userId = profile?.id;
  const [count, setCount] = useState(0);

  useEffect(() => {
    if (!userId) {
      setCount(0);
      return;
    }

    // Initial data fetch
    const loadInitial = async () => {
      const { data, error } = await supabase
        .from('conversations')
        .select('unread_a, unread_b')
        .or(`participant_a.eq.${userId},participant_b.eq.${userId}`);

      if (!error && data) {
        const total = data.reduce((sum, row) =>
          sum + (row.unread_a ?? 0) + (row.unread_b ?? 0), 0);
        setCount(total);
      }
    };

    loadInitial();

    // Real-time subscription for new/updated conversations.
    // One filter per postgres_changes handler, so subscribe as both
    // participant_a and participant_b.
    //
    // Use a unique channel name per mount to avoid Supabase returning a
    // cached, already-subscribed channel instance — which causes the
    // "cannot add postgres_changes callbacks after subscribe()" error.
    const channelName = `unread-messages-${userId}-${Date.now()}`;
    const channel = supabase
      .channel(channelName)
      .on('postgres_changes',
        { event: 'INSERT', schema: 'public', table: 'conversations', filter: `participant_a=eq.${userId}` },
        () => loadInitial()
      )
      .on('postgres_changes',
        { event: 'INSERT', schema: 'public', table: 'conversations', filter: `participant_b=eq.${userId}` },
        () => loadInitial()
      )
      .on('postgres_changes',
        { event: 'UPDATE', schema: 'public', table: 'conversations', filter: `participant_a=eq.${userId}` },
        () => loadInitial()
      )
      .on('postgres_changes',
        { event: 'UPDATE', schema: 'public', table: 'conversations', filter: `participant_b=eq.${userId}` },
        () => loadInitial()
      )
      .subscribe();

    return () => {
      void supabase.removeChannel(channel);
    };
  }, [userId]);

  return count;
}

import type { Env } from './env';
import { handlePaystackRequest } from './paystack';
import { handlePodJoinRequest } from './pod-join';

export type { Env };

interface ExpireResult {
  expired: number;
  ids: string[];
}

interface SlotCreditExpireResult extends ExpireResult {
  podsReconciled: number;
}

async function patchExpired(baseUrl: string, key: string, table: string, filter: string): Promise<ExpireResult> {
  const url = `${baseUrl}/rest/v1/${table}`;
  const response = await fetch(`${url}?${filter}`, {
    method: 'PATCH',
    headers: {
      'Content-Type': 'application/json',
      apikey: key,
      Authorization: `Bearer ${key}`,
      Prefer: 'return=representation',
    },
    body: JSON.stringify({ status: 'expired' }),
  });

  if (!response.ok) {
    const text = await response.text();
    throw new Error(`Supabase PATCH on ${table} failed: ${response.status} — ${text}`);
  }

  const updated = (await response.json()) as { id: string }[];
  return { expired: updated.length, ids: updated.map((r) => r.id) };
}

async function reconcileExpiredPods(baseUrl: string, key: string, expiredCreditIds: string[]): Promise<number> {
  if (expiredCreditIds.length === 0) {
    return 0;
  }
  const headers = {
    'Content-Type': 'application/json',
    apikey: key,
    Authorization: `Bearer ${key}`,
  };
  let reconciled = 0;
  for (const creditId of expiredCreditIds) {
    try {
      const response = await fetch(`${baseUrl}/rest/v1/rpc/reconcile_pod_after_credit_expiry`, {
        method: 'POST',
        headers,
        body: JSON.stringify({ p_slot_credit_id: creditId }),
      });
      if (!response.ok) {
        console.error(`[Expiration] Pod reconcile RPC failed for ${creditId}: ${response.status} — ${await response.text()}`);
        continue;
      }
      const podId = (await response.json()) as string | null;
      if (podId) {
        reconciled += 1;
      }
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      console.error(`[Expiration] Pod reconcile exception for ${creditId}: ${message}`);
    }
  }
  return reconciled;
}

async function expireStaleSlotCredits(env: Env): Promise<SlotCreditExpireResult> {
  const now = new Date().toISOString();
  const baseUrl = env.SUPABASE_URL.replace(/\/$/, '');
  const headers = {
    'Content-Type': 'application/json',
    apikey: env.SUPABASE_SERVICE_ROLE_KEY,
    Authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE_KEY}`,
    Prefer: 'return=representation',
  };

  let totalExpired = 0;
  let totalIds: string[] = [];

  const expiredBooked = await patchExpired(baseUrl, env.SUPABASE_SERVICE_ROLE_KEY, 'slot_credits', new URLSearchParams({
    status: 'eq.booked_pending_claim',
    payment_deadline: `lt.${now}`,
  }).toString());
  totalExpired += expiredBooked.expired;
  totalIds = totalIds.concat(expiredBooked.ids);

  const expiredPending = await patchExpired(baseUrl, env.SUPABASE_SERVICE_ROLE_KEY, 'slot_credits', new URLSearchParams({
    status: 'eq.pending_verification',
    payment_deadline: `lt.${now}`,
  }).toString());
  totalExpired += expiredPending.expired;
  totalIds = totalIds.concat(expiredPending.ids);

  const podsReconciled = await reconcileExpiredPods(baseUrl, env.SUPABASE_SERVICE_ROLE_KEY, totalIds);
  return { expired: totalExpired, ids: totalIds, podsReconciled };
}

async function expireStaleTourBookings(env: Env): Promise<ExpireResult> {
  const cutoff = new Date(Date.now() - 15 * 60 * 1000).toISOString();
  const baseUrl = env.SUPABASE_URL.replace(/\/$/, '');
  const params = new URLSearchParams({
    status: 'eq.pending_payment',
    created_at: `lt.${cutoff}`,
  });
  return patchExpired(baseUrl, env.SUPABASE_SERVICE_ROLE_KEY, 'tour_bookings', params.toString());
}

function summarize(result: ExpireResult | SlotCreditExpireResult, label: string): void {
  let message = `[Expiration] Expired ${result.expired} ${label}: ${result.ids.join(', ')}`;
  if ('podsReconciled' in result) {
    message += `; reconciled ${result.podsReconciled} pods`;
  }
  console.log(message);
}

export default {
  async scheduled(_event: ScheduledEvent, env: Env, _ctx: ExecutionContext) {
    const results = await Promise.allSettled([
      expireStaleSlotCredits(env),
      expireStaleTourBookings(env),
    ]);
    const labels = ['slot credits', 'pending tours'];
    results.forEach((result, index) => {
      if (result.status === 'fulfilled') {
        summarize(result.value, labels[index]);
      } else {
        console.error(`[Expiration] Error expiring ${labels[index]}:`, result.reason?.message || String(result.reason));
      }
    });
  },

  async fetch(request: Request, env: Env, _ctx: ExecutionContext): Promise<Response> {
    const url = new URL(request.url);
    if (url.pathname.startsWith('/api/paystack/')) {
      return handlePaystackRequest(request, env);
    }

    if (url.pathname.startsWith('/api/pods/')) {
      return handlePodJoinRequest(request, env);
    }

    if (request.method !== 'POST') {
      return new Response('Send a POST request to trigger expiration.', { status: 405 });
    }

    try {
      const [slotCredits, pendingTours] = await Promise.all([
        expireStaleSlotCredits(env),
        expireStaleTourBookings(env),
      ]);
      return new Response(JSON.stringify({ slotCredits, pendingTours }), {
        status: 200,
        headers: { 'Content-Type': 'application/json' },
      });
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      return new Response(JSON.stringify({ error: message }), {
        status: 500,
        headers: { 'Content-Type': 'application/json' },
      });
    }
  },
};
